#!/usr/bin/env python3
import sys, json, unicodedata

# Honorific list: remove leading honorifics (case‑insensitive, optional trailing period)
HONORIFICS = {
    'mr', 'mrs', 'ms', 'miss', 'mister', 'prof', 'professor',
    'sir', 'dr', 'doctor', 'lord', 'lady', 'capt', 'captain',
    'rev', 'reverend', 'hon', 'honorable',
}

# Common particles that should normally be lower‑cased unless they are the first or last word
PARTICLES = {
    'van', 'der', 'de', 'da', 'di', 'del', 'den', 'du', 'von', 'zu',
}

def read_input():
    """Read entire stdin."""
    return sys.stdin.read()

def parse_json(text):
    """Parse JSON and return the value of the 'name' key."""
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        sys.exit(2)
    if not isinstance(data, dict):
        sys.exit(2)
    name = data.get("name")
    if not isinstance(name, str):
        sys.exit(2)
    return name

def validate_length(name):
    """Ensure the name has at most 100 Unicode code points."""
    if len(name) > 100:
        sys.exit(2)

def collapse_whitespace(name):
    """Collapse runs of whitespace to a single space and strip."""
    return ' '.join(name.split())

def remove_honorifics(name):
    """Strip leading honorifics, case‑insensitive, optional period."""
    words = name.split()
    i = 0
    while i < len(words):
        w = words[i].rstrip('.')
        if w.lower() in HONORIFICS:
            i += 1
        else:
            break
    return ' '.join(words[i:])

def capitalize_word(word):
    """Capitalize the first letter of a word; also after hyphens/apostrophes/etc."""
    result = []
    capitalize_next = True
    for ch in word:
        if capitalize_next:
            result.append(ch.upper())
        else:
            result.append(ch.lower())
        if ch in "-'’.":
            capitalize_next = True
        else:
            capitalize_next = False
    return ''.join(result)

def normalize_display(name):
    """Apply G1–G5 to produce the display form."""
    words = name.split()
    normalized_words = []
    for idx, word in enumerate(words):
        # Hyphenated words: treat each sub‑word individually
        if '-' in word:
            parts = word.split('-')
            caps = [capitalize_word(part) for part in parts]
            normalized_words.append('-'.join(caps))
            continue

        lw = word.lower()
        # Handle particles (except first/last word and not part of hyphenated word)
        if lw in PARTICLES and idx not in (0, len(words) - 1):
            normalized_words.append(lw)
        else:
            normalized_words.append(capitalize_word(word))
    return ' '.join(normalized_words)

def generate_key(display):
    """Generate the key using NFKD, lower‑case, and strip non‑letters."""
    normalized = unicodedata.normalize('NFKD', display)
    letters = [c.lower() for c in normalized if unicodedata.category(c).startswith('L')]
    return ''.join(letters)

def main():
    text = read_input()
    name = parse_json(text)
    validate_length(name)
    name = collapse_whitespace(name)
    if not name:
        sys.exit(2)
    name = remove_honorifics(name)
    if not name:
        sys.exit(2)
    display = normalize_display(name)
    key = generate_key(display)
    output = {"display": display, "key": key}
    sys.stdout.write(json.dumps(output, ensure_ascii=False))
    sys.exit(0)

if __name__ == "__main__":
    main()

